sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    if (current.state == 2) {
        current.task_status = 'CLOSED_COMPLETE';
        return;
    }

    if (!current.data_review_status.changes() && !current.callback_and_checker_completed.changes()) {
        return;
    }

    // Business Rule: Calculate Field Value for Treasury Case
    function dataCheckerReviewTaskAllComplete() {
        try {
            var completed = current.number_of_checker_task == 1 && dataReviewStatusValue == "DATA_CHECKER_1_REVIEW_COMPLETED" || current.number_of_checker_task == 2 && dataReviewStatusValue == "DATA_CHECKER_2_REVIEW_COMPLETED";
            return completed;
        } catch (errorInfo) {
            gs.error("[iQube - Treasury]: Business Rule : Treasury Case.Case Status, Function : executeRule-dataCheckerReviewTaskAllComplete :- Unknown exception while processing" + errorInfo.message);
        }
    }

    try {
        // instruction / ITM
        var taskStatus = current.task_status || '';
        var statusValueAndDisplayValue = [current.task_status.getDisplayValue(), taskStatus];
        var INSTRUCITON_STATUS_LOWER_CASE = "instruction";
        var isInstruction = function(statusValue) {
            return !!statusValue && statusValue.toLowerCase().includes(INSTRUCITON_STATUS_LOWER_CASE);
        };
        // MSSTRESURY-1043
        var returnOriginValue = function(statusStr) {
            const skipCalculatedList = ["open", "PREPROCESSING_COMPLETED.SUCCESS", "PREPROCESSING_COMPLETED.FAIL", "EXTRACTION_COMPLETED.SUCCESS", "EXTRACTION_COMPLETED.FAIL", "STS_NEW_EXCEPTION", "TRIGGER_EXTRACTION", "INDEXING", "Canceled", "CLOSED_COMPLETE"];
            return skipCalculatedList.some(function(status) {
                return status == statusStr;
            });
        };
        if (returnOriginValue(taskStatus)) {
            current.task_status = taskStatus;
            return;
        }
        if (statusValueAndDisplayValue.some(isInstruction)) {
            current.task_status = taskStatus;
            return;
        }
        var dataReviewStatusValue = current.data_review_status.getValue();
        if (!(current.case_type == 'Instruction Case' && dataReviewStatusValue)) {
            // current.task_status = current.task_status;
            return;
        }

        var dataReviewStatus = current.data_review_status.getDisplayValue() || '';
        var calculated_value = '';
        var callbackStatus = current.callback_and_checker_completed.getDisplayValue() || '';
        if (dataReviewStatusValue == 'PENDING_DATA_MAKER_REVIEW' || dataReviewStatusValue == 'DATA_MAKER_REVIEW_COMPLETED') {
            current.task_status = dataReviewStatus;
            return;
        }

        if (callbackStatus === 'false') {
            callbackStatus = 'Callback is Not Required';
        }
        if (dataReviewStatus && callbackStatus) {

            if (dataCheckerReviewTaskAllComplete()) {
                calculated_value = "Data Checker Review Completed" + '; ' + callbackStatus;
            } else {
                calculated_value = dataReviewStatus + '; ' + callbackStatus;
            }
        } else if (!dataReviewStatus) {
            calculated_value = dataReviewStatus || callbackStatus || '';
        }
        current.task_status = calculated_value;
    } catch (e) {
        gs.error("[iQube - Treasury]:Business Rule = Treasury Case Status Calculation | Unknown exception while processing" + e.message);
    }

})(current, previous);
